    [Test]
    public void ZeroAndFillInPlace_VectorAndMatrix()
    {
        var v = new doubleN(4, Allocator.Temp);
        v.fillInPlace((double)3);
        for (int i = 0; i < 4; i++) Assert.AreEqual(3.0, (double)v[i], 1e-6);
        v.zeroInPlace();
        for (int i = 0; i < 4; i++) Assert.AreEqual(0.0, (double)v[i], 0.0);

        var m = new doubleMxN(3, 2, Allocator.Temp);
        m.fillInPlace((double)7);
        Assert.AreEqual(7.0, (double)m[0, 0], 1e-6);
        Assert.AreEqual(7.0, (double)m[2, 1], 1e-6);
        m.zeroInPlace();
        Assert.AreEqual(0.0, (double)m[0, 0], 0.0);
        Assert.AreEqual(0.0, (double)m[2, 1], 0.0);
    }

    [Test]
    public void IsCreated_Lifecycle_Standalone()
    {
        doubleN defVec = default;
        Assert.IsFalse(defVec.IsCreated);
        var v = new doubleN(3, Allocator.Persistent);
        Assert.IsTrue(v.IsCreated);
        v.Dispose();
        Assert.IsFalse(v.IsCreated);

        doubleMxN defMat = default;
        Assert.IsFalse(defMat.IsCreated);
        var m = new doubleMxN(2, 2, Allocator.Persistent);
        Assert.IsTrue(m.IsCreated);
        m.Dispose();
        Assert.IsFalse(m.IsCreated);
    }

    [Test]
    public void IsCreated_ArenaTracked_FalseAfterRecordDispose()
    {
        var arena = new Arena(Allocator.Persistent);
        try
        {
            var v = arena.doubleVec(3);
            Assert.IsTrue(v.IsCreated);
            v.Dispose();   // frees the record slot; the table itself stays alive
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            Assert.IsFalse(v.IsCreated);
#endif
            var m = arena.doubleMat(2, 2);
            Assert.IsTrue(m.IsCreated);
            m.Dispose();
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            Assert.IsFalse(m.IsCreated);
#endif
        }
        finally { arena.Dispose(); }
    }

    [Test]
    public void VectorView_AliasesArrayMemory()
    {
        var arr = new NativeArray<double>(4, Allocator.Temp);
        arr[2] = (double)5;

        var view = new doubleN(arr);
        Assert.IsTrue(view.IsCreated);
        Assert.AreEqual(4, view.N);
        Assert.AreEqual(5.0, (double)view[2], 1e-6);

        view[1] = (double)9;                       // write through the view...
        Assert.AreEqual(9.0, (double)arr[1], 1e-6); // ...lands in the array

        view.Dispose();   // must be a no-op: the array still owns the memory
        Assert.AreEqual(9.0, (double)arr[1], 1e-6);
        arr.Dispose();
    }

    [Test]
    public void MatrixView_AliasesArrayMemory_And_GuardsDims()
    {
        var arr = new NativeArray<double>(6, Allocator.Temp);
        var view = new doubleMxN(2, 3, arr);
        Assert.IsTrue(view.IsCreated);

        view[1, 2] = (double)8;                     // row-major: index 1*3+2 = 5
        Assert.AreEqual(8.0, (double)arr[5], 1e-6);

        Assert.Throws<ArgumentException>(() => { var bad = new doubleMxN(2, 2, arr); });
        arr.Dispose();
    }

    [Test]
    public void MatrixReslice_RealViewOverLeadingPrefix_And_GuardsBounds()
    {
        var buf = new doubleMxN(4, 4, Allocator.Temp);
        for (int i = 0; i < 16; i++) buf[i] = (double)i;

        var view = new doubleMxN(in buf, 2, 2);
        Assert.AreEqual(4, view.Length);
        Assert.AreEqual(4, view.Data.Length);
        Assert.AreEqual(2, view.M_Rows);
        Assert.AreEqual(2, view.N_Cols);

        // Tightly-packed prefix reading, NOT a stride-preserving "top-left corner of the 4x4"
        // (which would read view[1,0] == buf[4]).
        Assert.AreEqual(0.0, (double)view[0, 0], 0.0);
        Assert.AreEqual(1.0, (double)view[0, 1], 0.0);
        Assert.AreEqual(2.0, (double)view[1, 0], 0.0);
        Assert.AreEqual(3.0, (double)view[1, 1], 0.0);

        Assert.Throws<ArgumentException>(() => { var bad = new doubleMxN(in buf, 5, 4); });

        var full = new doubleMxN(in buf, 4, 4);
        Assert.AreEqual(16, full.Length);
        for (int i = 0; i < 16; i++) Assert.AreEqual((double)buf[i], (double)full[i], 0.0);
    }

    [Test]
    public void CopyToFrom_NativeArray_Roundtrip_And_Guards()
    {
        var v = new doubleN(3, Allocator.Temp);
        v[0] = (double)1; v[1] = (double)2; v[2] = (double)3;

        var arr = new NativeArray<double>(3, Allocator.Temp);
        v.CopyTo(arr);
        Assert.AreEqual(2.0, (double)arr[1], 1e-6);

        arr[1] = (double)20;
        v.CopyFrom(arr);
        Assert.AreEqual(20.0, (double)v[1], 1e-6);

        var wrong = new NativeArray<double>(2, Allocator.Temp);
        Assert.Throws<ArgumentException>(() => v.CopyTo(wrong));
        Assert.Throws<ArgumentException>(() => v.CopyFrom(wrong));

        var m = new doubleMxN(2, 2, Allocator.Temp);
        m[0, 0] = (double)1; m[1, 1] = (double)4;
        var marr = new NativeArray<double>(4, Allocator.Temp);
        m.CopyTo(marr);
        Assert.AreEqual(4.0, (double)marr[3], 1e-6);
        marr[0] = (double)10;
        m.CopyFrom(marr);
        Assert.AreEqual(10.0, (double)m[0, 0], 1e-6);
        Assert.Throws<ArgumentException>(() => m.CopyTo(wrong));
        Assert.Throws<ArgumentException>(() => m.CopyFrom(wrong));
    }

    [Test]
    public void Matrix_CopyToFrom_Matrix_Parity()
    {
        var a = new doubleMxN(2, 3, Allocator.Temp);
        a[1, 2] = (double)6;
        var b = new doubleMxN(2, 3, Allocator.Temp);

        a.CopyTo(b);
        Assert.AreEqual(6.0, (double)b[1, 2], 1e-6);

        b[0, 0] = (double)5;
        a.CopyFrom(b);
        Assert.AreEqual(5.0, (double)a[0, 0], 1e-6);

        var wrong = new doubleMxN(3, 2, Allocator.Temp);
        Assert.Throws<ArgumentException>(() => a.CopyTo(wrong));
        Assert.Throws<ArgumentException>(() => a.CopyFrom(wrong));
    }

    // Solve straight into a NativeArray through views, inside a Burst job — the
    // bridge's intended workflow: game state stays in NativeArrays, no boundary copy.
    [BurstCompile(CompileSynchronously = true)]
    struct ViewSolveJob : IJob
    {
        [ReadOnly] public NativeArray<double> B;
        public NativeArray<double> X;

        public void Execute()
        {
            int n = B.Length;
            var A = new doubleMxN(n, n, Allocator.Temp);
            for (int i = 0; i < n; i++) A[i, i] = (double)2;
            A[0, 1] = (double)1; A[1, 0] = (double)1;

            var x = new doubleN(X);   // view over the output array
            x.CopyFrom(B);            // rhs in, solved in place below
            CHO.solveInPlace(ref A, ref x);
        }
    }

    [Test]
    public void ViewSolveJob_WritesSolutionThroughView()
    {
        // A = [[2,1,0],[1,2,0],[0,0,2]], b = (3,3,2)  ->  x = (1,1,1)
        var b = new NativeArray<double>(3, Allocator.TempJob);
        var x = new NativeArray<double>(3, Allocator.TempJob);
        b[0] = (double)3; b[1] = (double)3; b[2] = (double)2;

        new ViewSolveJob { B = b, X = x }.Run();

        Assert.AreEqual(1.0, (double)x[0], 1e-4);
        Assert.AreEqual(1.0, (double)x[1], 1e-4);
        Assert.AreEqual(1.0, (double)x[2], 1e-4);

        b.Dispose(); x.Dispose();
    }
